function isArmstrong(n) {
  const str = n.toString();
  const power = str.length;
  let sum = 0;
  let temp = n;
  while (temp > 0) {
    sum += (temp % 10) ** power;
    temp = Math.floor(temp / 10);
  }
  return sum === n;
}
